// Canary weights to walk through, and the per-step measured error counts.
// threshold = max tolerated error rate (1%). A step PROMOTES only if its
// error rate <= threshold; the first breach ROLLS BACK and stops the ramp.
const threshold = 0.01;
const steps = [
  { weight: 5,  requests: 2000, errors: 6 },   // 0.30%
  { weight: 25, requests: 2000, errors: 14 },  // 0.70%
  { weight: 50, requests: 2000, errors: 240 }, // 12.00% -> breach
  { weight: 100, requests: 2000, errors: 0 },
];

let decision = 'PROMOTE 100%';
for (const s of steps) {
  const rate = s.errors / s.requests;
  if (rate > threshold) {
    decision = 'ROLLBACK at ' + s.weight + '%';
    break;
  }
}
console.log(decision);

// Kubernetes rounding: maxSurge rounds UP, maxUnavailable rounds DOWN.
function bounds(replicas, surgePct, unavailPct) {
  const surge = Math.ceil(replicas * surgePct / 100);
  const unavail = Math.floor(replicas * unavailPct / 100);
  const maxPods = replicas + surge;
  const minReady = replicas - unavail;
  return { maxPods, minReady };
}

const replicas = 10;
// risky default: 25% / 25%
const d = bounds(replicas, 25, 25);
// safe zero-downtime: surge 1 pod (10%), unavailable 0%
const z = bounds(replicas, 10, 0);

console.log('default maxPods=' + d.maxPods + ' minReady=' + d.minReady + ' | zero-downtime maxPods=' + z.maxPods + ' minReady=' + z.minReady);

